/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
 module TopModule
   #(parameter N = 7)
    (
     input    wire  rst ,
     input    wire  clk_in,
@@



    reg [3:0]            cnt ;
    always @(posedge clk_in or negedge rst) begin
       if ("'!rst) begin
          cnt    <= '"'b0 ;
+         clkp   <= 1'b0 ;
       end
-      else if (cnt == N-1) begin
-         cnt    <= 'b0 ;
-      end
       else begin
-         cnt    <= cnt + 1'b1 ;
-      end
-   end
-
-   reg                  clkp ;
-   always @(posedge clk_in or negedge rst) begin
-      if ("'!rst) begin
-         clkp <= 1'"'b0 ;
-      end
-      else if (cnt == (N>>1)) begin 
-        clkp <= 1 ;
-      end
-      else if (cnt == N-1) begin 
-        clkp <= 0 ;
+         if (cnt == N-1) begin
+            cnt <= 'b0 ;
+         end
+         else begin
+            cnt <= cnt + 1'b1 ;
+         end
+
+         if (cnt == 'b0) begin
+            clkp <= 1'b1 ;
+         end
+         else if (cnt == (N>>1)) begin
+            clkp <= 1'b0 ;
+         end
       end
    end

+   reg                  clkp ;

    reg                  clkn ;
    always @(negedge clk_in or negedge rst) begin
       if ("'!rst) begin
          clkn <= 1'"'b0 ;
       end
-      else if (cnt == (N>>1) ) begin 
-        clkn <= 1 ;
-      end
-      else if (cnt == N-1) begin 
-        clkn <= 0 ;
+      else begin
+         clkn <= clkp ;
       end
    end

-
-    always @(posedge clk or negedge rst_n) begin
-        if ("'!rst_n)
-            clk_out7 <= 1'"'b0;
-        else
-            clk_out7 <= clkp | clkn;
-    end
+   assign clk_out7 = clkp | clkn;
 endmodule
*** End Patch
PATCH

cat > tb.sv <<'TB'
"'`timescale 1ns/1ps
module tb;
  reg clk_in = 0;
  reg rst = 0;
  wire clk_out7;

  TopModule dut (
    .rst(rst),
    .clk_in(clk_in),
    .clk_out7(clk_out7)
  );

  always #5 clk_in = ~clk_in;

  integer edge_count = 0;
  time last_toggle = 0;
  initial begin
    $display("time clk rst cnt clkp clkn out");
    $monitor("%0t %0b %0b %0d %0b %0b %0b", $time, clk_in, rst, dut.cnt, dut.clkp, dut.clkn, clk_out7);
    #12 rst = 1;
    repeat (40) @(posedge clk_in);
    $finish;
  end

  always @(clk_out7) begin
    if (rst) begin
      if (edge_count > 0)
        $display("toggle at %0t, delta=%0t", $time, $time - last_toggle);
      last_toggle = $time;
      edge_count = edge_count + 1;
    end
  end
endmodule
TB

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

